import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_linear_relu_div_kernel(
    const float* x, const float* weight, const float* bias, float divisor,
    float* output, int batch_size, int in_features, int out_features) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_features) return;

    int batch_idx = idx / out_features;
    int out_idx = idx % out_features;

    float sum = 0.0f;
    for(int k = 0; k < in_features; ++k) {
        sum += x[batch_idx * in_features + k] * weight[out_idx * in_features + k];
    }
    sum += bias[out_idx];
    sum = fmaxf(sum, 0.0f) / divisor;
    output[idx] = sum;
}

torch::Tensor fused_linear_relu_div_cuda(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias, float divisor) {

    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, x.options());

    int total_elements = batch_size * out_features;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_linear_relu_div_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        divisor,
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_linear_relu_div_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, float divisor);"

fused_linear = load_inline(
    name='fused_linear',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=['fused_linear_relu_div_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, divisor):
        super(ModelNew, self).__init__()
        self.divisor = divisor
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused_linear.fused_linear_relu_div_cuda(x, self.weight, self.bias, self.divisor)
